INSERT INTO `web_content` VALUES (1,'Operational Excellence'),(2,'Lead and integrate company-wide continuous improvement efforts by championing a data-driven culture of operational excellence and leveraging Lean Six Sigma Black Belts, Green Belts, Kaizen teams, digital transformation initiatives, and other strategic improvement programs to systematically eliminate waste, reduce process variation, optimize productivity, improve quality, lower costs, and deliver sustainable business value.'),(3,'SAVED'),(4,'Cost Improvements Initiatives'),(5,'TRAINED'),(6,'in DMAIC Methodology'),(7,'PROJECTS'),(8,'Accomplished'),(9,'F4.0: A Journey to Operational Excellence'),(10,'A journey that involves applying the right tools to the right processes.'),(11,'An Operational Excellence through:'),(12,'✓ Teamwork'),(13,'✓ Empowered Employees'),(14,'✓ Engaged Employees'),(15,'Operational Excellence'),(16,'Success is not achieved by one giant leap, but by many small, deliberate steps that eventually help reach the summit.'),(17,'Operational Excellence Team'),(18,'Will drive all Continuous Improvement initiatives through Lean Six Sigma (Black Belt and Green Belt) programs, Kaizen teams, digital transformation initiatives, productivity improvements, cost reduction programs, and other strategic operational excellence efforts.'),(19,'Operational Excellence Program Framework'),(20,'Lead and integrate company-wide continuous improvement efforts by championing a data-driven culture of operational excellence and leveraging Lean Six Sigma Black Belts, Green Belts, Kaizen teams, digital transformation initiatives, and other strategic improvement programs to systematically eliminate waste, reduce process variation, optimize productivity, improve quality, lower costs, and deliver sustainable business value.'),(21,'./assets/uploads/1792718641866.png'),(22,'./assets/uploads/1792718593175.jpg'),(23,'./assets/uploads/1792718598399.jpg'),(24,'./assets/uploads/1792718603785.jpg'),(25,'./assets/uploads/1792718622606.mp4'),(26,'Our Factory 4.0 is shifting gears'),(27,'Before, we were just learning'),(28,'Now, we have turned the corner'),(29,'We are beginning to gain mileage'),(30,'It\'s time to push the pedal to the metal!'),(31,'Push Harder! Push Faster!'),(32,'To capitalize on our gains'),(33,'Welcome to'),(34,'Operational Excellence'),(35,'./assets/uploads/1792718679084.png'),(36,'Coaching &amp; Consulting'),(37,'Turn ideas into impact with personalized coaching, project support, <br> and data-driven improvement strategies.'),(38,'./assets/uploads/user_38.png'),(39,'Meet the Lean Six Sigma Green Belts'),(40,'Meet the Lean Six Sigma Black Belts'),(41,'The Business Metrics of Operational Excellence'),(42,'10 Year Strategic Plan'),(43,'Desciption.'),(44,'5 Year Strategic Plan'),(45,'Desciption.'),(46,'Annual Operating Plan'),(47,'Desciption.'),(48,'Factory KRA'),(49,'Desciption.'),(50,'Green Belt/Black Belt Programs'),(51,'Desciption.'),(52,'Lean Six Sigma Project Scopes'),(53,'Total'),(54,'Projects'),(55,'6 projects (35%) focused on Yield &amp; Quality improvement'),(56,'5 projects (29%) focused on Productivity &amp; Capacity enhancement'),(57,'Strong emphasis on Operational Excellence initiatives and Quality Improvement'),(58,'Additional projects target Efficiency, Cost, and Cycle Time reduction'),(59,'Yield + Quality'),(60,'Productivity/Capacity'),(61,'Cycle Time'),(62,'Quality/Efficiency'),(63,'Cost Savings'),(64,'Yield Improvement'),(65,'Quality'),(66,'Lean Six Sigma Opportunities'),(67,'Productivity &amp; Efficiency'),(68,'Yield Improvement'),(69,'Increased Productivity'),(70,'Capacity Optimization'),(71,'Cycle Time Reduction'),(72,'Cost Reduction'),(73,'Cost Avoidance'),(74,'Scrap Reduction'),(75,'Waste Elimination'),(76,'Quality Excellence'),(77,'Zero Defect'),(78,'Reduced Process Variation'),(79,'Standardization'),(80,'Customer Satisfaction'),(81,'Lean Six Sigma Participation'),(82,'The Team behind Operational Excellence'),(83,'Project Execution'),(84,'Resources'),(85,'Process Ownership'),(86,'Technical Expertise'),(87,'Automation'),(88,'NPI Support'),(89,'Engineering'),(90,'Defect Reduction'),(91,'Customer Requirement'),(92,'Quality'),(93,'Inventory Optimization'),(94,'Planning'),(95,'Supply Chain'),(96,'Training'),(97,'Data Systems'),(98,'Digital Tools'),(99,'HR/IT'),(100,'Project Execution'),(101,'Maintenance'),(102,'IoT Initiatives'),(103,'Facilities'),(104,'Donald Cruz'),(105,'Operational Excellence Lead'),(106,'PMO/SPC'),(107,'Senior Engineer'),(108,'Imelda Cruz'),(109,'Head of Operational Excellence'),(110,'Greg Fisher'),(111,'Appointed Vice President'),(112,'./assets/uploads/user_112.png'),(113,'./assets/uploads/user_113.jpg'),(114,'./assets/uploads/user_114.jpg'),(115,'Purpose'),(116,'Empowering innovation to enhance the human experience.'),(117,'Vision'),(118,'Microchip Technology is in Everything.'),(119,'Mission'),(120,'Our mission is to make innovative design easier through comprehensive total system solutions that address critical challenges at the intersection of emerging technologies and durable end markets.'),(121,'We measure our success by winning the hearts of our customers, shareholders, employees and communities and by continuously improving all aspects of our business to drive profitable growth.'),(122,'House of Quality'),(123,'Microchip\'s Quality Policy'),(124,'In order to meet or exceed customer expectations at a reduced cost, we encourage our employees to support continuous improvement, anticipate problems and implement root cause solutions.'),(125,'Guiding Values'),(126,'Quality Comes First'),(127,'Customers Are Our Focus'),(128,'Employees Are Our Greatest Strength'),(129,'We are on a relentless quest for perfection and are committed to the goal of zero defects. We will perform correctly the first time and maintain our company’s quality management system certifications to ensure customer satisfaction. We employ the aggregate system so that all employees anticipate problems and implement root-cause solutions using effective and standardized improvement methods. We believe that quality is built in and not inspected in and that when quality comes first, reduced costs follow.'),(130,'We embrace that exceptional customer service is everyone’s responsibility. Our highest priority is to make our customer’s life easier by understanding their needs, removing barriers to innovation, and consistently exceeding their expectations. We believe each employee must effectively serve their internal customers for Microchip’s external customers to be properly served.'),(131,'We design jobs and provide opportunities promoting employee teamwork, productivity, creativity, pride in work, trust, integrity, fairness iinvolvement, development and empowerment. We base recognition, advancement and compensation on an employee’s achievement of excellence in company, team and individual performance. We provide for employee health and welfare by offering competitive and comprehensive employee benefits.'),(132,'Profits and Growth Provide for Everything We Do'),(133,'We strive to deliver industry-leading customer value that drives profits and growth, which fuel our future innovations, expand employee opportunities and represent the overall success of Microchip. We accomplish this by aggressively  pursuing product and sales competitiveness, optimization of inventory levels and effective cashflow management.'),(134,'Products and Technology Are Our Foundation'),(135,'We are dedicated to empowering our customers with a broad portfolio of technology solutions while protecting our intellectual properties with a robust patent portfolio. By continuously investing in the design and development of our processes, products, software and services, we ensure that our innovations are timely, reliable and cost-effective.'),(136,'Suppliers, Representatives and Distributors Are Our Partners'),(137,'We strive to maintain professional and mutually beneficial partnerships with suppliers, representatives, distributors, design houses and consultants who are an integral link in the achievement of our mission and guiding values.'),(138,'Safety and Security Are Never Compromised'),(139,'We place our concern for the health, safety and security of our employees, company, property, personal data and community at the forefront of our decisions, policies and actions. We are all individually and collectively responsible for safety and security.'),(140,'Total Cycle Times Are Optimized'),(141,'We focus resources to optimize cycle times to our internal and external customers by empowering employees to achieve efficient cycle times in their area of responsibility. We believe that cycle time reduction is achieved by streamlining processes through the systematic removal of barriers to productivity.'),(142,'Communication Is Vital'),(143,'We encourage appropriate, honest, constructive and timely communication in company, customer, investor, government and community relationships to resolve issues, exchange information and share knowledge.'),(144,'Continuous Improvement Is Essential'),(145,'We utilize the concept of “Vital Few” to establish our priorities. We are committed to proactive problem solving by fostering a sense of urgency, intellectual curiosity and a desire to improve everyday efficiency. We encourage personal initiative, honest self-criticism and proactive questioning that drive increased productivity, innovation and organizational agility.'),(146,'Professional Ethics and Social Responsibility Are Practiced'),(147,'We manage our business and treat customers, employees, shareholders, investors, suppliers, channel partners, community and government in a manner that exemplifies our honesty, ethics and integrity. We honor our short- and long-term fiscal, social and environmental responsibilities and are proud to serve as an equal opportunity employer.');
